import { DomainError, ERROR_CODES } from '../domain/errors.ts';

export interface PageQuery {
    offset: number;
    limit: number;
}

export interface Page<T> {
    items: T[];
    total: number;
    offset: number;
    limit: number;
    nextOffset: number | null;
}

export function objectInput(value: unknown): Record<string, unknown> {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new DomainError(ERROR_CODES.INVALID_ORDER, 'Request must be an object');
    }
    return value as Record<string, unknown>;
}

export function stringInput(value: unknown, name: string): string {
    if (typeof value !== 'string' || !value.trim()) {
        throw new DomainError(ERROR_CODES.INVALID_ORDER, `${name} is required`);
    }
    return value.trim();
}

export function optionalString(value: unknown, name: string): string | undefined {
    if (value === undefined) return undefined;
    return stringInput(value, name);
}

export function integerInput(value: unknown, name: string, minimum = 0, maximum = Number.MAX_SAFE_INTEGER): number {
    if (typeof value !== 'number' && typeof value !== 'string') {
        throw new DomainError(ERROR_CODES.INVALID_ORDER, `${name} must be an integer`);
    }
    if (value === '') {
        throw new DomainError(ERROR_CODES.INVALID_ORDER, `${name} must be an integer`);
    }
    const number = Number(value);
    if (!Number.isSafeInteger(number) || number < minimum || number > maximum) {
        throw new DomainError(ERROR_CODES.INVALID_ORDER, `${name} is out of range`);
    }
    return number;
}

export function pageQuery(input: Record<string, unknown>): PageQuery {
    return {
        offset: input.offset === undefined ? 0 : integerInput(input.offset, 'offset'),
        limit: input.limit === undefined ? 20 : integerInput(input.limit, 'limit', 1, 100),
    };
}

export function page<T>(values: T[], query: PageQuery): Page<T> {
    const items = values.slice(query.offset, query.offset + query.limit);
    const next = query.offset + items.length;
    return {
        items,
        total: values.length,
        offset: query.offset,
        limit: query.limit,
        nextOffset: next < values.length ? next : null,
    };
}

export function arrayInput(value: unknown, name: string, maximum = 100): unknown[] {
    if (!Array.isArray(value) || value.length === 0 || value.length > maximum) {
        throw new DomainError(ERROR_CODES.INVALID_ORDER, `${name} must be a nonempty bounded array`);
    }
    return value;
}

