import {OrderService, type OrderFilters} from '../services/order-service.ts';
import {objectInput,optionalString,integerInput,page,pageQuery} from './request.ts';
import type {RouteRegistry} from './route-registry.ts';

function filters(input: Record<string,unknown>): OrderFilters {
    const result: OrderFilters = {};
    const memberId = optionalString(input.memberId,'memberId');
    if (memberId !== undefined) {
        result.memberId = memberId;
    }
    const status = optionalString(input.status,'status');
    if (status !== undefined) {
        if (!['draft','paid','partially-refunded','refunded','cancelled'].includes(status)) {
            throw new Error('Unknown order status');
        }
        result.status = status as OrderFilters['status'];
    }
    if (input.from !== undefined) {
        result.from = integerInput(input.from,'from');
    }
    if (input.to !== undefined) {
        result.to = integerInput(input.to,'to');
    }
    if (result.from !== undefined && result.to !== undefined && result.from > result.to) {
        throw new Error('Order interval is invalid');
    }
    return result;
}

export function registerOrderRoutes(registry: RouteRegistry, service: OrderService): void {
    registry.register({
        method:'GET',
        path:'/orders',
        handler:(value: unknown) => {
            const query = objectInput(value);
            const matched = service.list(filters(query));
            if (query.offset === undefined && query.limit === undefined) {
                return matched;
            }
            return page(matched,pageQuery(query));
        },
    });
    registry.register({
        method:'GET',
        path:'/orders/export',
        handler:(value: unknown) => {
            const query = objectInput(value);
            return service.exportRows(filters(query));
        },
    });
    registry.register({
        method:'GET',
        path:'/orders/count',
        handler:(value: unknown) => {
            const query = objectInput(value);
            return service.count(filters(query));
        },
    });
}

