    private readonly store: OrderStore;
    constructor(store: OrderStore) { this.store = store; }
    create(order: Order): Order { return this.store.save(order); }
    get(id: string): Order { const order = this.store.get(id); if (!order) throw new Error('Order not found'); return order; }
    list(filters: OrderFilters = {}): Order[] {
        return this.store.all().filter(order => {
            if (filters.memberId && order.memberId !== filters.memberId) return false;
            if (filters.status && order.status !== filters.status) return false;
            if (filters.minTotalCents !== undefined && orderTotal(order).cents < filters.minTotalCents) return false;
            if (filters.minRefundCents !== undefined && refundTotal(order).cents < filters.minRefundCents) return false;
            if (filters.from !== undefined && order.createdAt < filters.from) return false;
