import type { RouteRegistry } from './route-registry.ts';
import type { EventStore } from '../storage/event-store.ts';
import { objectInput, stringInput } from './request.ts';
import { downloadTopicEvents } from '../services/topic-download.ts';
export function registerTopicDownloadRoutes(registry: RouteRegistry, store: EventStore): void {
    registry.register({
        method: 'GET',
        path: '/events/topic',
        handler: (value: unknown) => {
            const query = objectInput(value);
            const topic = stringInput(query.topic, 'topic');
            return downloadTopicEvents(store, topic);
        },
    });
}

